import { createError, toError } from "../../../errors/index.js";
export function composeMiddleware(globalMiddlewares, registry) {
    return (context, finalNext) => {
        let index = -1;
        const pathname = new URL(context.req.url).pathname;
        const chain = [...globalMiddlewares];
        for (const { pattern, use } of registry) {
            if (pattern.test(pathname))
                chain.push(...use);
        }
        function dispatch(i) {
            if (i <= index) {
                throw toError(createError({ type: "api", message: "next() called multiple times" }));
            }
            index = i;
            if (i === chain.length) {
                return Promise.resolve(finalNext());
            }
            const middleware = chain[i];
            if (!middleware)
                return Promise.resolve(undefined);
            return Promise.resolve(middleware(context, () => dispatch(i + 1)));
        }
        return dispatch(0);
    };
}
